def check_solution(x):
    n = len(x)
    if sorted(x) != list(range(n)):
        return False, "Not a permutation of 0..7"

    d = [abs(x[i+1] - x[i]) for i in range(n-1)]
    if sorted(d) != list(range(1, n)):
        return False, "Differences are not a permutation of 1..7"

    if x[4] != 2:
        return False, f"x[4] is {x[4]}, expected 2"

    if d[5] != 2:
        return False, f"d[5] is {d[5]}, expected 2"

    return True, "Valid"

x = [0, 7, 1, 6, 2, 5, 3, 4]
print(check_solution(x))
